-- YottaFlex synthetic database SQL seed
PRAGMA foreign_keys=OFF;

BEGIN TRANSACTION;
CREATE TABLE accounts (
	account_id VARCHAR(30) NOT NULL, 
	customer_id VARCHAR(30) NOT NULL, 
	account_status VARCHAR(20) NOT NULL, 
	opened_date DATE NOT NULL, 
	PRIMARY KEY (account_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);
CREATE TABLE collection_cases (
	case_id VARCHAR(40) NOT NULL, 
	loan_id VARCHAR(40) NOT NULL, 
	case_status VARCHAR(20) NOT NULL, 
	priority_score NUMERIC(8, 2) NOT NULL, 
	assigned_to VARCHAR(100), 
	opened_at DATETIME NOT NULL, 
	closed_at DATETIME, 
	closure_reason VARCHAR(100), 
	PRIMARY KEY (case_id), 
	FOREIGN KEY(loan_id) REFERENCES loans (loan_id)
);
CREATE TABLE contact_attempts (
	contact_attempt_id VARCHAR(60) NOT NULL, 
	case_id VARCHAR(40) NOT NULL, 
	channel VARCHAR(20) NOT NULL, 
	attempted_at DATETIME NOT NULL, 
	outcome VARCHAR(30) NOT NULL, 
	agent_id VARCHAR(40), 
	notes TEXT, 
	PRIMARY KEY (contact_attempt_id), 
	FOREIGN KEY(case_id) REFERENCES collection_cases (case_id)
);
CREATE TABLE contact_preferences (
	preference_id VARCHAR(40) NOT NULL, 
	customer_id VARCHAR(30) NOT NULL, 
	channel VARCHAR(20) NOT NULL, 
	allowed BOOLEAN NOT NULL, 
	preferred_start_time VARCHAR(10), 
	preferred_end_time VARCHAR(10), 
	effective_from DATE NOT NULL, 
	effective_to DATE, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (preference_id), 
	FOREIGN KEY(customer_id) REFERENCES customers (customer_id)
);
CREATE TABLE customers (
	customer_id VARCHAR(30) NOT NULL, 
	full_name VARCHAR(120) NOT NULL, 
	email VARCHAR(150), 
	phone VARCHAR(20) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (customer_id), 
	UNIQUE (email)
);
CREATE TABLE delinquency_snapshots (
	snapshot_id VARCHAR(40) NOT NULL, 
	loan_id VARCHAR(40) NOT NULL, 
	snapshot_date DATE NOT NULL, 
	days_past_due INTEGER NOT NULL, 
	arrears_amount NUMERIC(12, 2) NOT NULL, 
	risk_category VARCHAR(20) NOT NULL, 
	hardship_flag BOOLEAN NOT NULL, 
	dispute_flag BOOLEAN NOT NULL, 
	notes TEXT, 
	PRIMARY KEY (snapshot_id), 
	CONSTRAINT ck_snapshot_dpd_nonnegative CHECK (days_past_due >= 0), 
	CONSTRAINT ck_snapshot_arrears_nonnegative CHECK (arrears_amount >= 0), 
	FOREIGN KEY(loan_id) REFERENCES loans (loan_id)
);
CREATE TABLE installments (
	installment_id VARCHAR(60) NOT NULL, 
	loan_id VARCHAR(40) NOT NULL, 
	installment_number INTEGER NOT NULL, 
	due_date DATE NOT NULL, 
	due_amount NUMERIC(12, 2) NOT NULL, 
	paid_amount NUMERIC(12, 2) NOT NULL, 
	installment_status VARCHAR(20) NOT NULL, 
	PRIMARY KEY (installment_id), 
	CONSTRAINT ck_installment_due_positive CHECK (due_amount > 0), 
	CONSTRAINT ck_installment_paid_nonnegative CHECK (paid_amount >= 0), 
	FOREIGN KEY(loan_id) REFERENCES loans (loan_id)
);
CREATE TABLE loans (
	loan_id VARCHAR(40) NOT NULL, 
	account_id VARCHAR(30) NOT NULL, 
	principal_amount NUMERIC(12, 2) NOT NULL, 
	interest_rate NUMERIC(5, 2) NOT NULL, 
	loan_status VARCHAR(20) NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE, 
	PRIMARY KEY (loan_id), 
	CONSTRAINT ck_loan_principal_positive CHECK (principal_amount > 0), 
	CONSTRAINT ck_loan_interest_nonnegative CHECK (interest_rate >= 0), 
	FOREIGN KEY(account_id) REFERENCES accounts (account_id)
);
CREATE TABLE payments (
	payment_id VARCHAR(40) NOT NULL, 
	loan_id VARCHAR(40) NOT NULL, 
	installment_id VARCHAR(60), 
	case_id VARCHAR(40), 
	payment_amount NUMERIC(12, 2) NOT NULL, 
	payment_date DATE NOT NULL, 
	payment_status VARCHAR(20) NOT NULL, 
	payment_reference VARCHAR(80), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (payment_id), 
	CONSTRAINT ck_payment_amount_positive CHECK (payment_amount > 0), 
	FOREIGN KEY(loan_id) REFERENCES loans (loan_id), 
	FOREIGN KEY(installment_id) REFERENCES installments (installment_id), 
	FOREIGN KEY(case_id) REFERENCES collection_cases (case_id), 
	UNIQUE (payment_reference)
);
CREATE TABLE promises_to_pay (
	promise_id VARCHAR(60) NOT NULL, 
	case_id VARCHAR(40) NOT NULL, 
	promised_amount NUMERIC(12, 2) NOT NULL, 
	promised_date DATE NOT NULL, 
	promise_status VARCHAR(20) NOT NULL, 
	created_at DATETIME NOT NULL, 
	fulfilled_at DATETIME, 
	PRIMARY KEY (promise_id), 
	CONSTRAINT ck_promise_amount_positive CHECK (promised_amount > 0), 
	FOREIGN KEY(case_id) REFERENCES collection_cases (case_id)
);
COMMIT;
